package io.github.sanamhub.nepdate.codegen

import java.nio.file.Files
import java.nio.file.Path
import java.nio.file.Paths
import kotlin.io.path.createDirectories
import kotlin.io.path.readText
import kotlin.io.path.writeText
import kotlin.system.exitProcess

const val HEADER = "// Generated by :codegen. DO NOT EDIT.\n\n"
const val CALENDAR_JSON = "shared/data/calendar/bs-calendar.json"
const val CALENDAR_OUTPUT = "nepdate/src/main/kotlin/io/github/sanamhub/nepdate/Calendar.generated.kt"

/** Generated files under [root], relative path to content. */
fun generate(root: Path): Map<String, String> {
    val calendar = parseCalendar(root.resolve(CALENDAR_JSON).readText())
    return mapOf(
        CALENDAR_OUTPUT to renderCalendar(calendar),
        PATRO_OUTPUT to renderPatro(buildPatroTables(readPatroDays(root, calendar))),
    )
}

/** Days of every `shared/data/patro/<year>.json`, read in ascending year. */
fun readPatroDays(
    root: Path,
    calendar: CalendarData,
): List<PatroDay> {
    val files =
        Files.list(root.resolve(PATRO_DIR)).use { stream ->
            stream.filter { it.fileName.toString().endsWith(".json") }.toList()
        }
    return files
        .map { file ->
            val year =
                file.fileName
                    .toString()
                    .removeSuffix(".json")
                    .toIntOrNull()
            if (year == null) throw CodegenException("$PATRO_DIR/${file.fileName}: name is not <year>.json")
            year to file
        }.sortedBy { it.first }
        .flatMap { (year, file) -> parsePatroFile(year, file.readText(), calendar) }
}

/**
 * Writes the generated files under [root], or with [check] compares them and writes nothing.
 * Returns the process exit code: 0, or 1 when [check] finds a difference.
 */
fun runCodegen(
    root: Path,
    check: Boolean,
): Int {
    var differences = 0
    for ((relative, content) in generate(root)) {
        val path = root.resolve(relative)
        if (check) {
            if (!Files.exists(path) || path.readText() != content) {
                System.err.println("$relative differs from shared/data: run ./gradlew :codegen:run")
                differences++
            }
        } else {
            path.parent.createDirectories()
            path.writeText(content)
            println("wrote $relative")
        }
    }
    return if (differences == 0) 0 else 1
}

fun main(args: Array<String>) {
    val check = "--check" in args
    val code =
        try {
            runCodegen(Paths.get("").toAbsolutePath(), check)
        } catch (e: CodegenException) {
            System.err.println("codegen: ${e.message}")
            1
        }
    exitProcess(code)
}
